    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    z: DATA_TYPE[n] @ DRAM
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    for k in seq(1, n):
        # Update beta based on the previous reflection coefficient
        beta = (1.0 - alpha * alpha) * beta
        sum = 0.0

        # Compute the inner product sum_{i=0..k-1} r[k-i-1] * y[i]
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # New reflection coefficient
        alpha = -(r[k] + sum) / beta

        # Update temporary solution vector z based on current y and alpha
        for i in seq(0, k):
            z[i] = y[i] + alpha * y[k - i - 1]

        # Commit the updated values back into y
        for i in seq(0, k):
            y[i] = z[i]

        # Set the new coefficient at position k
        y[k] = alpha


