    # Tail iterations are handled with guards so correctness is preserved
    kernel_durbin_opt = divide_loop(kernel_durbin_opt, i_loop, strip, ("io", "ii"), tail="guard")

    # After the split, there are (idx + 1) "ii" loops; unroll the newest one
    ii_loop = kernel_durbin_opt.find_loop(f"ii #{idx}")
    kernel_durbin_opt = unroll_loop(kernel_durbin_opt, ii_loop)

