EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline Durbin kernel written in Exo.  This is algebraically
# equivalent to the PolyBench reference implementation, but uses an
# in-place symmetric update to avoid the temporary z array and reduce
# memory traffic.
@proc
def durbin_base(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    for k in seq(1, n):
        beta = (1.0 - alpha * alpha) * beta
        sum = 0.0

        # Dot product: sum = sum_{i=0}^{k-1} r[k-i-1] * y[i]
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        alpha = -(r[k] + sum) / beta

        # In-place symmetric update of y to avoid an auxiliary array z.
        #
        # The original algorithm does:
        #   for i in 0..k-1:
        #       z[i] = y[i] + alpha * y[k-i-1]
        #   for i in 0..k-1:
        #       y[i] = z[i]
        #
        # For each pair (i, j) with j = k-i-1 and i < j, this yields:
        #   y_new[i] = y_old[i] + alpha * y_old[j]
        #   y_new[j] = y_old[j] + alpha * y_old[i]
        #
        # We can compute these two updates in place using only scalars:
        #   yi = y_old[i]; yj = y_old[j]
        #   y[i] = yi + alpha * yj
        #   y[j] = yj + alpha * yi
        #
        # This preserves the exact arithmetic for each pair and removes
        # an extra read/write pass over y.
        for i in seq(0, k / 2):
            yi: DATA_TYPE
            yj: DATA_TYPE

            yi = y[i]
            yj = y[k - i - 1]

            y[i]         = yi + alpha * yj
            y[k - i - 1] = yj + alpha * yi

        # If k is odd, there is a center element that pairs with itself.
        # For that index m = k/2 (integer division), the original code
        # computes:
        #   y_new[m] = y_old[m] + alpha * y_old[m]
        if k % 2 == 1:
            y[k / 2] = y[k / 2] + alpha * y[k / 2]

        # The last element updated in this iteration.
        y[k] = alpha


# --------------------------------------------------------------------
# Scheduling: optimize inner loops for better ILP and locality.
# We keep the outer k loop sequential (it is inherently recurrent),
# but we restructure and unroll the inner i loops.
# --------------------------------------------------------------------

p = durbin_base

# 1) Optimize the dot-product loop over i inside each k-iteration.
#    - Split i into an outer/io and inner/ii loop with factor 4.
#    - Fully unroll the small inner loop (ii), exposing straight-line
#      code that the C compiler can vectorize.
i_sum = p.find_loop("i")                    # first 'i' loop: the dot-product
p = divide_loop(p, i_sum, 4, ("io", "ii"), tail="cut")
p = unroll_loop(p, p.find_loop("ii"))

