#    unrolled group updates four disjoint (i, k-i-1) pairs, so the
#    transformation remains safe.
i_update = p.find_loop("i")                # now the remaining 'i' loop
p = divide_loop(p, i_update, 4, ("jo", "ji"), tail="cut")
p = unroll_loop(p, p.find_loop("ji"))

# Clean up expressions after loop transformations.
p = simplify(p)

# Export the scheduled kernel under the name expected by the C driver.
kernel_durbin = rename(p, "kernel_durbin")
